  $$ select jsonb_array_elements($json$[{"code":"O1C-01","module_code":"M-O1-CASCADE","position":1,"wording":"I can clearly describe how my work contributes to our team's goals.","response_kind":"agree5","anchors":null,"is_reverse":false,"online":true,"portal_code":false},{"code":"O1C-02","module_code":"M-O1-CASCADE","position":2,"wording":"I can clearly describe how my team's goals connect to the organisation's broader priorities.","response_kind":"agree5","anchors":null,"is_reverse":false,"online":true,"portal_code":false},{"code":"O1C-03","module_code":"M-O1-CASCADE","position":3,"wording":"I know what our organisation is trying to achieve and why.","response_kind":"agree5","anchors":null,"is_reverse":false,"online":true,"portal_code":false},{"code":"O1C-04","module_code":"M-O1-CASCADE","position":4,"wording":"When priorities change at the organisation level, the implications for my work are explained clearly.","response_kind":"agree5","anchors":null,"is_reverse":false,"online":true,"portal_code":false},{"code":"O1C-05","module_code":"M-O1-CASCADE","position":5,"wording":"Sometimes I find myself doing work that doesn't seem to connect to what the organisation is trying to achieve.","response_kind":"agree5","anchors":null,"is_reverse":true,"online":true,"portal_code":false},{"code":"O2I-01","module_code":"M-O2-IA","position":1,"wording":"When I need information to do my work, I can find it without significant delay.","response_kind":"agree5","anchors":null,"is_reverse":false,"online":true,"portal_code":false},{"code":"O2I-02","module_code":"M-O2-IA","position":2,"wording":"The information available to me is accurate and current.","response_kind":"agree5","anchors":null,"is_reverse":false,"online":true,"portal_code":false},{"code":"O2I-03","module_code":"M-O2-IA","position":3,"wording":"I often need to ask colleagues for information that should be available in our systems.","response_kind":"agree5","anchors":null,"is_reverse":true,"online":true,"portal_code":false},{"code":"O2I-04","module_code":"M-O2-IA","position":4,"wording":"I spend significant time each week working around limitations in our tools or systems.","response_kind":"agree5","anchors":null,"is_reverse":true,"online":true,"portal_code":false},{"code":"O2I-05","module_code":"M-O2-IA","position":5,"wording":"The systems I use to do my work integrate well with each other.","response_kind":"agree5","anchors":null,"is_reverse":false,"online":true,"portal_code":false},{"code":"O2I-06","module_code":"M-O2-IA","position":6,"wording":"I sometimes have to re-enter or copy information between systems that should connect automatically.","response_kind":"agree5","anchors":null,"is_reverse":true,"online":true,"portal_code":false},{"code":"O2I-07","module_code":"M-O2-IA","position":7,"wording":"What is the single most significant tool or information access issue in your work? (Optional, open-text)","response_kind":"open_text","anchors":null,"is_reverse":false,"online":false,"portal_code":false},{"code":"O3P-01","module_code":"M-O3-PF","position":1,"wording":"This process is clear and easy to follow.","response_kind":"agree5","anchors":null,"is_reverse":false,"online":true,"portal_code":false},{"code":"O3P-02","module_code":"M-O3-PF","position":2,"wording":"Work moves through this process without unnecessary delays or approvals.","response_kind":"agree5","anchors":null,"is_reverse":false,"online":true,"portal_code":false},{"code":"O3P-03","module_code":"M-O3-PF","position":3,"wording":"Information and inputs are typically ready when this process needs them.","response_kind":"agree5","anchors":null,"is_reverse":false,"online":true,"portal_code":false},{"code":"O3P-04","module_code":"M-O3-PF","position":4,"wording":"When something needs to be reworked or corrected in this process, the rework usually slows it down significantly.","response_kind":"agree5","anchors":null,"is_reverse":true,"online":true,"portal_code":false},{"code":"O3P-05","module_code":"M-O3-PF","position":5,"wording":"Handoffs in this process (between people, teams or systems) work smoothly.","response_kind":"agree5","anchors":null,"is_reverse":false,"online":true,"portal_code":false},{"code":"O3P-06","module_code":"M-O3-PF","position":6,"wording":"I spend appropriate time on the value-adding parts of this process, not on admin or workarounds.","response_kind":"agree5","anchors":null,"is_reverse":false,"online":true,"portal_code":false},{"code":"O3P-07","module_code":"M-O3-PF","position":7,"wording":"Where in this process is the biggest bottleneck or source of friction? (Optional, open-text)","response_kind":"open_text","anchors":null,"is_reverse":false,"online":false,"portal_code":false},{"code":"O1L-01","module_code":"M-O1-LT","position":1,"wording":"Who Recommends this decision?","response_kind":"rapid_multi","anchors":null,"is_reverse":false,"online":true,"portal_code":true},{"code":"O1L-02","module_code":"M-O1-LT","position":2,"wording":"Who Agrees must be consulted before this decision?","response_kind":"rapid_multi","anchors":null,"is_reverse":false,"online":true,"portal_code":true},{"code":"O1L-03","module_code":"M-O1-LT","position":3,"wording":"Who Performs (implements) this decision?","response_kind":"rapid_multi","anchors":null,"is_reverse":false,"online":true,"portal_code":true},{"code":"O1L-04","module_code":"M-O1-LT","position":4,"wording":"Who provides Input on this decision?","response_kind":"rapid_multi","anchors":null,"is_reverse":false,"online":true,"portal_code":true},{"code":"O1L-05","module_code":"M-O1-LT","position":5,"wording":"Who Decides (has decision authority) on this decision?","response_kind":"rapid_single","anchors":null,"is_reverse":false,"online":true,"portal_code":true},{"code":"O1L-06","module_code":"M-O1-LT","position":6,"wording":"How clear are the decision rights for this type of decision?","response_kind":"anchored5","anchors":[{"value":1,"label":"Very unclear","description":null},{"value":5,"label":"Very clear","description":null}],"is_reverse":false,"online":true,"portal_code":true},{"code":"C1M-01","module_code":"M-C1-MGR","position":1,"wording":"[Skill name]: rate this person's current demonstrated proficiency","response_kind":"anchored5","anchors":[{"value":1,"label":"Novice","description":null},{"value":2,"label":"Developing","description":null},{"value":3,"label":"Proficient","description":null},{"value":4,"label":"Advanced","description":null},{"value":5,"label":"Expert","description":null}],"is_reverse":false,"online":true,"portal_code":true},{"code":"C2M-01","module_code":"M-C2-MGR","position":1,"wording":"[Domain name]: rate this person's current working knowledge","response_kind":"anchored5","anchors":[{"value":1,"label":"Little working knowledge","description":null},{"value":2,"label":"Basic; needs frequent reference or help","description":null},{"value":3,"label":"Sound working knowledge for the role","description":null},{"value":4,"label":"Deep knowledge; handles non-routine cases","description":null},{"value":5,"label":"An authority others consult","description":null}],"is_reverse":false,"online":true,"portal_code":true},{"code":"C3M-01","module_code":"M-C3-MGR","position":1,"wording":"Performance band","response_kind":"band5","anchors":[{"value":1,"label":"Underperforming","description":"Consistent gaps in delivery; performance management intervention warranted"},{"value":2,"label":"Developing / partial meet","description":"Meets some expectations; gaps in delivery quality or scope"},{"value":3,"label":"Meeting expectations","description":"Delivers reliably at the role's expected standard"},{"value":4,"label":"Exceeding expectations","description":"Consistently delivers above the role's expected standard"},{"value":5,"label":"Exceptional contributor","description":"Consistently exceeds expectations in scope and quality; recognised as a top performer"}],"is_reverse":false,"online":true,"portal_code":true},{"code":"C3M-02","module_code":"M-C3-MGR","position":2,"wording":"Evidence basis","response_kind":"evidence_note","anchors":null,"is_reverse":false,"online":true,"portal_code":true},{"code":"C5L-01","module_code":"M-C5-TL","position":1,"wording":"How long does it typically take for a new team member to make their first meaningful contribution?","response_kind":"anchored5","anchors":[{"value":1,"label":">12 weeks","description":null},{"value":2,"label":"8-12 weeks","description":null},{"value":3,"label":"4-8 weeks","description":null},{"value":4,"label":"2-4 weeks","description":null},{"value":5,"label":"<2 weeks","description":null}],"is_reverse":false,"online":true,"portal_code":false},{"code":"C5L-02","module_code":"M-C5-TL","position":2,"wording":"How structured is your team's onboarding for new members?","response_kind":"anchored5","anchors":[{"value":1,"label":"No structure","description":null},{"value":5,"label":"Highly structured with clear milestones","description":null}],"is_reverse":false,"online":true,"portal_code":false},{"code":"C5L-03","module_code":"M-C5-TL","position":3,"wording":"When a new tool or process is introduced, how long until your team is using it productively?","response_kind":"anchored5","anchors":[{"value":1,"label":">90 days","description":null},{"value":5,"label":"<30 days","description":null}],"is_reverse":false,"online":true,"portal_code":false},{"code":"C5L-04","module_code":"M-C5-TL","position":4,"wording":"How smoothly does your team adopt new tools or processes?","response_kind":"anchored5","anchors":[{"value":1,"label":"Significant resistance/disruption","description":null},{"value":5,"label":"Smooth and rapid","description":null}],"is_reverse":false,"online":true,"portal_code":false},{"code":"C5L-05","module_code":"M-C5-TL","position":5,"wording":"How often does your team formally review what worked and what didn't on completed work?","response_kind":"anchored5","anchors":[{"value":1,"label":"Never","description":null},{"value":2,"label":"Rarely","description":null},{"value":3,"label":"Sometimes","description":null},{"value":4,"label":"Regularly","description":null},{"value":5,"label":"After every significant piece of work","description":null}],"is_reverse":false,"online":true,"portal_code":false},{"code":"C5L-06","module_code":"M-C5-TL","position":6,"wording":"When your team identifies a learning from a retrospective, how reliably does it get applied to subsequent work?","response_kind":"anchored5","anchors":[{"value":1,"label":"Rarely","description":null},{"value":5,"label":"Almost always","description":null}],"is_reverse":false,"online":true,"portal_code":false},{"code":"C5L-07","module_code":"M-C5-TL","position":7,"wording":"How regularly does your team share learning or new knowledge across team members?","response_kind":"anchored5","anchors":[{"value":1,"label":"Rarely","description":null},{"value":5,"label":"As a regular practice","description":null}],"is_reverse":false,"online":true,"portal_code":false},{"code":"C5L-08","module_code":"M-C5-TL","position":8,"wording":"When a team member learns something new and useful, how easily does the rest of the team gain access to that knowledge?","response_kind":"anchored5","anchors":[{"value":1,"label":"Difficult","description":null},{"value":5,"label":"Effortless","description":null}],"is_reverse":false,"online":true,"portal_code":false},{"code":"C5L-09","module_code":"M-C5-TL","position":9,"wording":"How safe is it for your team members to try new approaches that might not work?","response_kind":"anchored5","anchors":[{"value":1,"label":"Not safe — failures are penalised","description":null},{"value":5,"label":"Very safe — experimentation is encouraged","description":null}],"is_reverse":false,"online":true,"portal_code":false},{"code":"C5L-10","module_code":"M-C5-TL","position":10,"wording":"How does your team treat mistakes and failures?","response_kind":"anchored5","anchors":[{"value":1,"label":"Punitive","description":null},{"value":5,"label":"As learning opportunities","description":null}],"is_reverse":false,"online":true,"portal_code":false},{"code":"C5L-11","module_code":"M-C5-TL","position":11,"wording":"How readily does your team accept the temporary or permanent transfer of team members to or from other teams?","response_kind":"anchored5","anchors":[{"value":1,"label":"Significant friction","description":null},{"value":5,"label":"Smooth and embraced","description":null}],"is_reverse":false,"online":true,"portal_code":false},{"code":"C5L-12","module_code":"M-C5-TL","position":12,"wording":"How actively does your team consume external learning (industry conferences, courses, professional reading)?","response_kind":"anchored5","anchors":[{"value":1,"label":"Minimally","description":null},{"value":5,"label":"Highly actively","description":null}],"is_reverse":false,"online":true,"portal_code":false}]$json$::jsonb) $$,
  'ref_module_items holds exactly the generated rows'
);

