select set_eq(
  $$ select to_jsonb(t) from public.ref_admin_checklist_facts t $$,
  $$ select jsonb_array_elements($json$[{"code":"RA-1","checklist_code":"ADM-O1","position":1,"wording":"A written position description exists and was reviewed or updated within the last 24 months.","response_kind":"yes_no","source_response":null},{"code":"RA-2","checklist_code":"ADM-O1","position":2,"wording":"The position description states success measures or accountabilities, not only duties.","response_kind":"yes_no","source_response":null},{"code":"RA-3","checklist_code":"ADM-O1","position":3,"wording":"The position description, or a delegations document it refers to, states the decisions the role can make without approval.","response_kind":"yes_no","source_response":null},{"code":"TI-1","checklist_code":"ADM-O2","position":1,"wording":"The system has a named owner accountable for it.","response_kind":"yes_no","source_response":"Yes 1, No 0"},{"code":"TI-2","checklist_code":"ADM-O2","position":2,"wording":"The system is on a current, vendor-supported version.","response_kind":"yes_no","source_response":"Yes 1, No 0"},{"code":"TI-3","checklist_code":"ADM-O2","position":3,"wording":"The system does the job the unit needs without routine offline workarounds such as spreadsheets or re-keying.","response_kind":"yes_partly_no","source_response":"Yes 1, Partly 0.5, No 0"},{"code":"INT-1","checklist_code":"ADM-O2","position":4,"wording":"How data moves between this system and the others the unit relies on.","response_kind":"integration","source_response":"Automated integration 100; scheduled import or export 60; manual re-entry 20; not connected but should be 0; does not need to connect (excluded)"},{"code":"CF-1","checklist_code":"ADM-O4","position":1,"wording":"Workload to capacity (utilisation), %","response_kind":"percent","source_response":"80 to 95 = 100; 95 to 105 or 70 to 80 = 75; 105 to 115 or 60 to 70 = 55; above 115 or below 60 = 25"},{"code":"CF-2","checklist_code":"ADM-O4","position":2,"wording":"Hours worked per FTE per week above standard","response_kind":"hours","source_response":"up to 1 = 100; 1 to 2 = 85; 2 to 4 = 65; 4 to 6 = 45; above 6 = 20"},{"code":"CF-3","checklist_code":"ADM-O4","position":3,"wording":"Unplanned absence against the organisation's own 12-month baseline","response_kind":"percent","source_response":"at or below = 100; up to 10% above = 75; 10 to 25% above = 55; more than 25% above = 25"},{"code":"CF-4","checklist_code":"ADM-O4","position":4,"wording":"Change in open backlog over the last three months","response_kind":"percent_or_na","source_response":"shrinking or stable (within 5%) = 100; growing 5 to 25% = 55; growing more than 25% = 25; not applicable (excluded)"},{"code":"CF-5","checklist_code":"ADM-O4","position":5,"wording":"Vacancy rate against approved establishment","response_kind":"percent","source_response":"up to 3% = 100; 3 to 6 = 85; 6 to 10 = 65; 10 to 15 = 45; above 15 = 20"}]$json$::jsonb) $$,
  'ref_admin_checklist_facts holds exactly the generated rows'
);

